const raw = $input.first().json;
// n8n Webhook typeVersion 2 neste le body sous $json.body
const d = (raw.body && typeof raw.body === 'object') ? raw.body : raw;

// Construire le message utilisateur pour Claude
const lignes = [
  'Nom: ' + (d.nom || ''),
  'Email: ' + (d.email || ''),
  d.entreprise ? 'Entreprise: ' + d.entreprise : null,
  d.telephone ? 'Téléphone: ' + d.telephone : null,
  'Secteur / Catégorie: ' + (d.categorie || ''),
  'Titre de la demande: ' + (d.titre || ''),
  'Description: ' + (d.description || ''),
  (d.budget_min || d.budget_max)
    ? 'Budget: ' + (d.budget_min || '?') + '€ – ' + (d.budget_max || '?') + '€'
    : 'Budget: non précisé',
  d.delai ? 'Délai souhaité: ' + d.delai : 'Délai: non précisé',
  d.quantite ? 'Quantité estimée: ' + d.quantite : null,
].filter(Boolean).join('\n');

const requestBody = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 512,
  system: "Tu es l'assistant de CNL Sourcing. Analyse cette demande de sourcing et réponds UNIQUEMENT en JSON avec ces champs : secteur (string), urgence (1-5), budget_estime (string), delai_souhaite (string), resume (string de max 2 phrases naturelles). Pas de Markdown, pas d'explication, juste le JSON brut.",
  messages: [{ role: 'user', content: lignes }]
};

// Aplatir les données du formulaire pour les noeuds suivants
return [{ json: { ...d, _claudeBody: JSON.stringify(requestBody) } }];

const resp = $input.first().json;
// Récupérer les données du formulaire depuis le noeud Préparer (qui a déjà aplati le body)
const d = $('Préparer Analyse Claude').first().json;

// Parser la réponse JSON de Claude
let analyse = {};
try {
  const rawText = resp.content[0].text;
  // Nettoyer les éventuels backticks markdown
  const cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  analyse = JSON.parse(cleaned);
} catch (e) {
  analyse = {
    secteur: d.categorie || 'Non précisé',
    urgence: 3,
    budget_estime: 'À définir',
    delai_souhaite: d.delai || 'Non précisé',
    resume: 'Nouvelle demande reçue. Analyse manuelle requise.'
  };
}

// Emoji urgence
const urgenceEmoji = ['', '🟢', '🟡', '🟠', '🔴', '🚨'][analyse.urgence] || '⚪';

// Message Telegram (format HTML)
const lines = [
  '<b>🆕 Nouvelle demande CNL Sourcing !</b>',
  '',
  '<b>Client :</b> ' + (d.nom || '') + (d.prenom ? ' ' + d.prenom : '') + (d.entreprise ? ' — ' + d.entreprise : ''),
  '<b>Email :</b> ' + (d.email || '') + (d.telephone ? ' · ' + d.telephone : ''),
  '',
  '<b>Secteur :</b> ' + analyse.secteur,
  '<b>Urgence :</b> ' + urgenceEmoji + ' ' + analyse.urgence + '/5',
  '<b>Budget estimé :</b> ' + analyse.budget_estime,
  '<b>Délai :</b> ' + analyse.delai_souhaite,
  '',
  '<b>Résumé :</b>',
  analyse.resume,
  '',
  '🔗 <a href="https://cnlsourcing.com/admin">Voir dans l\'admin</a>'
];

// Valeurs SQL-safe (échapper les apostrophes)
const escapeSql = (s) => String(s || '').replace(/'/g, "''");

return [{
  json: {
    ...d,
    analyse,
    rawResponse: resp.content[0]?.text || '',
    telegramText: lines.join('\n'),
    // Champs pré-échappés pour SQL
    sql_resume: escapeSql(analyse.resume),
    sql_rawResponse: escapeSql(resp.content[0]?.text || ''),
    sql_secteur: escapeSql(analyse.secteur)
  }
}];
